const orig = $("[100_Master] Generate API Key & Workspace").item.json;
const welcomeMsg = `Welcome to our AI Cloud, ${orig.name}! Your workspace ${orig.workspaceId} is active. Your API Key is: ${orig.apiKey}`;
const messageFormatted = `🚀 *Welcome to Tech Startup Platform!* 🚀\n\n👤 *Name:* ${orig.name}\n🔑 *API Key:* ${orig.apiKey}\n🏢 *Workspace:* ${orig.workspaceId}\n📦 *Tier:* ${orig.plan} (${orig.monthlyCredit.toLocaleString()} credits)\n\n📖 *Quickstart Guide:* https://docs.yourstartup.io/quickstart`;

return {
  json: {
    ...orig,
    welcomeMsg,
    messageFormatted
  }
};

const m = $json.messages?.[0];
if (!m?.text?.body) return null;
return { json: { channel: 'whatsapp', chat: m.from, text: m.text.body } };

const m = $json.message;
if (!m?.text) return null;
return { json: { channel: 'telegram', chat: String(m.chat.id), text: m.text } };

const num = v => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const y = $now.setZone('Asia/Kolkata').minus({ days: 1 }).toFormat('yyyy-LL-dd'), t = $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd');
const rows = n => $(n).all().map(i => i.json);
const on = (a, d) => a.filter(r => String(r.Date || r.Created || r.Received || r.Added || '').slice(0, 10) === d);
const S = on(rows('Sales'), y), E = on(rows('Expenses'), y);
return [{ json: { date: $now.setZone('Asia/Kolkata').minus({ days: 1 }).toFormat('d LLL'), sales: S.reduce((s, r) => s + num(r.Amount), 0), bills: S.length, spent: E.reduce((s, r) => s + num(r.Amount), 0),
  new_leads: on(rows('Leads'), y).length, open_tickets: rows('Tickets').filter(r => r.Status && !/closed|resolved|done/i.test(r.Status)).length,
  tasks_today: on(rows('Tasks'), t).length, low_stock: rows('Stock').filter(r => r.SKU && num(r['In stock']) <= num(r['Reorder level'])).map(r => r.Item).slice(0, 8) } }];

return ($input.first().json.places || [])
  .filter(p => p.websiteUri)
  .map(p => ({ json: { business: p.displayName?.text, website: p.websiteUri, rating: p.rating, reviews: p.userRatingCount, address: p.formattedAddress, maps: p.googleMapsUri } }));

return $input.all().map((item, i) => {
  const biz = $("[01] One row per business").all()[i].json;
  const html = String(item.json.data || '');
  const title = (html.match(/<title[^>]*>([^<]*)/i) || [])[1] || '';
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 2500);
  const signals = { online_booking: /book (online|now)|appointment/i.test(html), chat_widget: /intercom|tawk|crisp|livechat|whatsapp/i.test(html) };
  return { json: { ...biz, title, text, signals } };
});

