// body: { "token": 12 } = the token being served now. Alert the customer who is next and the one 2 away.
// Tokens tab: Date (yyyy-mm-dd), Token, Name, Phone, Service, Status
const now = Number($("[13] Next customer button").first().json.body.token);
const rows = $input.all().map(i => i.json).filter(r => r.Token);
const out = [];
for (const r of rows) {
  const gap = Number(r.Token) - now;
  if (gap === 1) out.push({ ...r, Status: 'alerted: next', msg: `⏰ Hello ${r.Name} ji, you are NEXT (token #${r.Token}) at YOUR BUSINESS NAME. Please come to the counter.` });
  if (gap === 2) out.push({ ...r, Status: 'alerted: 2 away', msg: `Hello ${r.Name} ji, only 1 customer is before you (token #${r.Token}). Please reach YOUR BUSINESS NAME in about 10 minutes 🙏` });
  if (Number(r.Token) === now) out.push({ ...r, Status: 'serving', msg: '' });
}
return out.map(json => ({ json }));

