// Candidates tab: Name, Email, Phone, Role, Status (shortlisted -> invited), Interview
// Interview slots: weekdays at these times (IST), 45 minutes each. Edit to suit you.
const TIMES = ['11:00', '12:30', '15:00', '16:30'];
const MINUTES = 45;
const busy = $("[30] Busy times (next 5 days)").all().map(i => i.json).filter(e => e.start?.dateTime)
  .map(e => [DateTime.fromISO(e.start.dateTime), DateTime.fromISO(e.end.dateTime)]);
const slots = [];
for (let d = 1; d <= 6; d++) {
  const day = $now.setZone('Asia/Kolkata').plus({ days: d }).startOf('day');
  if (day.weekday === 7) continue; // no Sundays
  for (const t of TIMES) {
    const [h, m] = t.split(':').map(Number);
    const s = day.set({ hour: h, minute: m }), e = s.plus({ minutes: MINUTES });
    if (!busy.some(([bs, be]) => s < be && e > bs)) slots.push([s, e]);
  }
}
const cands = $("[30] Shortlisted candidates").all().map(i => i.json).filter(r => r.Email && r.Name);
return cands.slice(0, slots.length).map((r, i) => ({ json: { ...r, start: slots[i][0].toISO(), end: slots[i][1].toISO(),
  when: slots[i][0].toFormat("cccc, d LLL 'at' h:mm a") } }));

