// Deadlines tab: Filing (e.g. GSTR-3B), Due date (yyyy-mm-dd), Applies to (service tag, e.g. GST)
// Clients tab: Client, Phone, Services (comma tags, e.g. GST, ITR, TDS), Status
const today = $now.setZone('Asia/Kolkata').startOf('day');
const ALERT_DAYS = [7, 3, 1];
const out = [];
for (const { json: d } of $("[37] Deadlines").all()) {
  if (!d['Due date']) continue;
  const left = Math.round(DateTime.fromISO(d['Due date']).diff(today, 'days').days);
  if (!ALERT_DAYS.includes(left)) continue;
  for (const { json: cl } of $("[37] Active clients").all()) {
    const tags = String(cl.Services || '').split(',').map(s => s.trim());
    if (!cl.Phone || !tags.includes(d['Applies to'])) continue;
    out.push({ json: { Phone: cl.Phone, Client: cl.Client, Filing: d.Filing, Due: DateTime.fromISO(d['Due date']).toFormat('d LLL'), left,
      msg: `⏰ ${cl.Client} ji, *${d.Filing}* ki last date *${DateTime.fromISO(d['Due date']).toFormat('d LLL')}* hai (${left} din baaki).\n` +
           (left === 1 ? 'Kal last date hai – late fee se bachne ke liye aaj hi documents bhej dijiye 🙏' : 'Documents jaldi bhej dijiye taaki time pe file ho jaye.') } });
  }
}
return out;

// Pending docs tab: Client, Phone, Document, Asked on (yyyy-mm-dd), Reminders, Status
// stage 1 = day 2 (polite), 2 = day 5 (firm), 3 = day 9 (deadline risk), after that → alert the owner instead
const STAGES = { 2: 1, 5: 2, 9: 3 };
const out = [];
for (const { json: r } of $input.all()) {
  if (!r.Phone || !r['Asked on']) continue;
  const days = Math.round($now.startOf('day').diff(DateTime.fromISO(r['Asked on']), 'days').days);
  if (STAGES[days]) out.push({ json: { ...r, days, stage: STAGES[days], escalate: false } });
  else if (days === 12) out.push({ json: { ...r, days, stage: 4, escalate: true } });
}
return out;

// Stock tab: SKU, Item, In stock, Reorder level, Unit, Vendor, Last alert (yyyy-mm-dd)
const num = v => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const today = $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd');
const low = $input.all().map(i => i.json).filter(r => r.SKU && num(r['In stock']) <= num(r['Reorder level']) && r['Last alert'] !== today)
  .map(r => ({ SKU: r.SKU, Item: r.Item, left: num(r['In stock']), reorder: num(r['Reorder level']), unit: r.Unit || 'pcs', vendor: r.Vendor || '-' }));
return low.length ? [{ json: { count: low.length, items: low } }] : [];

// Stock tab: SKU, Item, In stock, Reorder level, Order qty, Unit, Vendor, Last price
// Vendors tab: Vendor, Contact, Email, Phone
const num = v => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const V = Object.fromEntries($("[40] Vendors").all().map(i => [i.json.Vendor, i.json]));
const low = $("[40] Stock").all().map(i => i.json).filter(r => r.SKU && r.Vendor && num(r['In stock']) <= num(r['Reorder level']));
const groups = {};
for (const r of low) (groups[r.Vendor] ||= []).push({ SKU: r.SKU, Item: r.Item, qty: num(r['Order qty']) || num(r['Reorder level']) * 2, unit: r.Unit || 'pcs', rate: num(r['Last price']) });
const stamp = $now.setZone('Asia/Kolkata').toFormat('yyMMdd');
return Object.entries(groups).filter(([v]) => V[v]?.Email).map(([v, items], i) => ({ json: { po: `PO-${stamp}-${String(i + 1).padStart(2, '0')}`, vendor: v,
  contact: V[v].Contact || v, email: V[v].Email, items, total: items.reduce((s, x) => s + x.qty * x.rate, 0) } }));

