parameters.jsCode:
// Tasks tab: Date (yyyy-mm-dd), Task, Assigned to, Priority (high/normal), Where / notes
// Staff tab: Name, Phone
const P = Object.fromEntries($("[42] Staff").all().map(i => [String(i.json.Name).trim(), i.json.Phone]));
const g = {};
for (const { json: t } of $('Today\'s tasks').all()) if (t.Task && t['Assigned to']) (g[String(t['Assigned to']).trim()] ||= []).push({ task: t.Task, priority: t.Priority || 'normal', notes: t['Where / notes'] || '' });
return Object.entries(g).filter(([n]) => P[n]).map(([name, tasks]) => ({ json: { name, phone: P[name], tasks } }));

// Competitors tab: Name, URL (pricing / menu / offers page), Last hash, Last text, Last checked, Last change
const clean = h => String(h || '').replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>|<noscript[\s\S]*?<\/noscript>/gi, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();
const hash = s => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return String(h >>> 0); };
const comp = $("[43] Competitors").item.json;
const text = clean($json.data).slice(0, 5000);
const h = hash(text);
return { json: { Name: comp.Name, URL: comp.URL, old_text: comp['Last text'] || '', new_text: text, hash: h,
  first_time: !comp['Last hash'], changed: !!comp['Last hash'] && String(comp['Last hash']) !== h && text.length > 50 } };

