return { json: { Name: r.Name, 'Last hash': r.hash, 'Last text': r.new_text, 'Last checked': $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd'),
  'Last change': ai ? ai.output.summary : (r.first_time ? 'first snapshot saved' : 'no change'), _important: ai ? ai.output.important : false, _changed: !!ai } };

const ch = $("[43] Snapshot row").all().map(i => i.json).filter(r => r._changed);
if (!ch.length) return [];
return [{ json: { text: `🕵️ Competitor watch (${ch.length} changed):

` + ch.sort((a, b) => b._important - a._important).map(r => `${r._important ? '🔴' : '•'} *${r.Name}*: ${r['Last change']}`).join('

') } }];

// Track tab: Product, URL, CSS selector (where the price is, e.g. .a-price-whole), Last price, Lowest, Alert below (optional ₹)
const t = $("[44] Track list").item.json;
const raw = Array.isArray($json.price) ? $json.price[0] : $json.price;
const price = Number(String(raw || '').replace(/[^0-9.]/g, '')) || null;
const last = Number(t['Last price']) || null, low = Number(t.Lowest) || price, below = Number(t['Alert below']) || 0;
return { json: { Product: t.Product, URL: t.URL, price, last, found: !!price, dropped: !!price && !!last && price < last,
  hit_target: !!price && below > 0 && price <= below, lowest: price ? Math.min(price, low || price) : low } };

