const o = $json.output, f = $("[48] Paste transcript").item.json;
const L = a => (a || []).map(x => '• ' + x).join('
') || '• none';
return { json: { title: `Notes – ${f['Meeting title']} – ${$now.setZone('Asia/Kolkata').toFormat('d LLL yyyy')}`,
  body: `SUMMARY
${o.summary}

DECISIONS
${L(o.decisions)}

ACTION ITEMS
${L((o.actions || []).map(a => `${a.task} – ${a.owner} – due ${a.due}`))}

OPEN QUESTIONS
${L(o.open_questions)}` } };

const o = $("[48] AI writes notes").first().json.output, f = $("[48] Paste transcript").first().json;
return (o.actions || []).map(a => ({ json: { Meeting: f['Meeting title'], Date: $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd'), Task: a.task, Owner: a.owner, Due: a.due, Status: 'open',
  Notes: 'https://docs.google.com/document/d/' + $("[48] Create Google Doc").first().json.id } }));

// Each tab needs a date column: Date / Created / Received / Added (yyyy-mm-dd ...). Amount columns: Sales.Amount, Expenses.Amount
const num = v => Number(String(v ?? '').replace(/[^0-9.-]/g, '')) || 0;
const start = $now.setZone('Asia/Kolkata').minus({ days: 6 }).startOf('day');
const week = n => $(n).all().map(i => i.json).filter(r => { const d = String(r.Date || r.Created || r.Received || r.Added || '').slice(0, 10); return d && DateTime.fromISO(d, { zone: 'Asia/Kolkata' }) >= start; });
const L = week('Leads'), S = week('Sales'), E = week('Expenses'), T = week('Tickets'), K = week('Tasks');
const sum = a => a.reduce((s, r) => s + num(r.Amount), 0);
const st = (a, k) => a.reduce((m, r) => (m[r[k] || 'unknown'] = (m[r[k] || 'unknown'] || 0) + 1, m), {});
return [{ json: { week: `${start.toFormat('d LLL')} – ${$now.setZone('Asia/Kolkata').toFormat('d LLL yyyy')}`, leads: L.length, lead_status: st(L, 'Status'), lead_sources: st(L, 'Source'),
  sales_count: S.length, sales: sum(S), spent: sum(E), net: sum(S) - sum(E), top_spend: Object.entries(E.reduce((m, r) => (m[r.Category || 'Other'] = (m[r.Category || 'Other'] || 0) + num(r.Amount), m), {})).sort((a, b) => b[1] - a[1]).slice(0, 3),
  tickets: T.length, ticket_status: st(T, 'Status'), high_priority: T.filter(r => String(r.Priority).toLowerCase() === 'high').length,
  tasks: K.length, tasks_done: K.filter(r => String(r.Status).toLowerCase() === 'done').length } }];

